82	    /// Add an origin span to all contained properties.
83	    pub fn spanned(mut self, span: Span) -> Self {
84	        for entry in self.0.make_mut() {
85	            if let Style::Property(property) = &mut **entry {
86	                property.span = span;
87	            }
88	        }
89	        self
90	    }
