516	        f.write_str("Show(")?;
517	        if let Some(selector) = &self.selector {
518	            selector.fmt(f)?;
519	            f.write_str(", ")?;
520	        }
521	        self.transform.fmt(f)?;
522	        f.write_str(")")
523	    }
